      const trigger = bundle.documents.find((d) => keywordPresent(d.text, expeditedAnchors));
      if (!trigger) return { pass: true, evidence: 'HMSA (Blue Cross Blue Shield of Hawaii) packet without an expedited / urgent request; rule vacuously satisfied.' };
      const urgencyAnchors = ['jeopardize', 'life or health', 'urgent clinical', 'time-sensitive', 'time sensitive', 'risk to life', 'regain maximum function', 'clinically urgent', 'rapidly progressing', 'severe pain'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, urgencyAnchors));
      if (!found) return { pass: false, note: 'HMSA (Blue Cross Blue Shield of Hawaii) request asks for expedited / urgent handling (' + trigger.name + ') but states no clinical urgency. Document why a standard-timeframe decision would jeopardize the member\'s life, health, or ability to regain maximum function.' };
