      const found = bundle.documents.find((d) => clinicalRoles.has(d.role));
      if (!found) return { pass: false, note: 'Medi-Cal (California Medicaid) packet carries no clinical document (clinical note, medical-necessity letter, lab, imaging, or pathology report). Attach the supporting medical records Medi-Cal (California Medicaid) requires for the determination.' };
      return { pass: true, evidence: 'Supporting clinical document present: ' + found.name + ' (' + found.role + ')' };
