      const refAnchors = ['authorization number', 'reference number', 'prior authorization number', 'auth number', 'auth #', 'case number', 'preauthorization number', 'certification number'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, refAnchors));
      if (!found) return { pass: false, note: 'Medi-Cal (California Medicaid) service requires prior authorization (' + trigger.name + ') but no authorization / reference number is documented. Obtain authorization before the service date and record the reference number.' };
