      const found = bundle.documents.find((d) => keywordPresent(d.text, rationaleAnchors));
      if (!found) return { pass: false, note: 'Ohio Medicaid outpatient surgery is requested in a hospital-outpatient setting without a documented medical-necessity rationale for that site. The site-of-care policy expects an ASC / freestanding facility unless an exception is documented.' };
