      const found = bundle.documents.find((d) => clinicalRoles.has(d.role));
      if (!found) return { pass: false, note: 'Georgia Medicaid packet carries no clinical document (clinical note, medical-necessity letter, lab, imaging, or pathology report). Attach the supporting medical records Georgia Medicaid requires for the determination.' };
      return { pass: true, evidence: 'Supporting clinical document present: ' + found.name + ' (' + found.role + ')' };
