      const channelAnchors = ['promise', 'promise provider portal', 'pa medicaid portal', 'pennsylvania medicaid portal', 'medical assistance portal', 'electronic data interchange', ' edi ', '278 transaction', 'edi 278', 'secure provider', 'provider portal', 'dhs.pa.gov'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, channelAnchors));
      if (!found) return { pass: false, note: 'No Pennsylvania Medicaid submission channel (the PROMISe portal / EDI 278 / the phone number on the member ID card) is noted in the packet. Informational only -- does not affect medical-necessity review.' };
