      const channelAnchors = ['champs', 'mi medicaid portal', 'michigan medicaid portal', 'electronic data interchange', ' edi ', '278 transaction', 'edi 278', 'secure provider', 'provider portal', 'michigan.gov'];
      const found = bundle.documents.find((d) => keywordPresent(d.text, channelAnchors));
      if (!found) return { pass: false, note: 'No Michigan Medicaid submission channel (the CHAMPS portal / EDI 278 / the phone number on the member ID card) is noted in the packet. Informational only -- does not affect medical-necessity review.' };
      return { pass: true, evidence: 'Submission channel reference in ' + found.name };
