      const drugAnchors = ['specialty medication', 'specialty drug', 'step therapy', 'step-therapy', 'prescription drug', 'physician-administered drug', 'infusion', 'non-preferred', 'formulary exception', 'north carolina medicaid pharmacy', 'pharmacy prior authorization'];
